/* MIT. Window and fixed unboxed quest tracker. All current original quests are side quests. */
static void ui_quest_bar65(int x,int y,int width,uint32_t id){uint64_t done,total;if(!quest_progress65(id,&done,&total))return;pb_fill(x,y,width,5,0xff000000);pb_fill(x+1,y+1,width-2,3,0xffeaf0f5);int fill=(int)(done*(width-2)/total);if(fill)pb_fill(x+1,y+1,fill,3,0xffedbfd1);}
static void ui_quest_window65(WindowUI*u,int focus,int inside){int x=windowX[UI_QUESTS],y=windowY[UI_QUESTS],count=quest_count65(),choice=u->choice[UI_QUESTS];ui_panel(x,y,160,110,"Quests",focus,inside&&choice==-1);if(choice>=count)choice=count?count-1:-1;u->choice[UI_QUESTS]=choice;int first=choice<0?0:choice/3*3;for(int i=first;i<count&&i<first+3;i++){uint32_t id=quest_at65(i);int yy=y+22+(i-first)*24;ui_cell(x+4,yy-1,152,23,inside&&choice==i);pb_fill(x+7,yy+4,7,7,quest_tracked65(id)?0xff6aabef:0xffeaf0f5);ui_fit47(x+19,yy,133,.85f,quest_title65(id));ui_quest_bar65(x+19,yy+15,131,id);}if(!count)ui_scaled(x+8,y+25,.85f,"No recorded quests.");ui_hint64(x+8,y+95,.75f,"A: track/untrack");}
static void ui_quest_tracker65(const WindowUI*u){if(!alwaysShowQuests65||(u->open&(1u<<UI_QUESTS)))return;int y=126;unsigned shown=0;for(unsigned i=0;i<quest_count65()&&shown<3;i++){uint32_t id=quest_at65(i);if(!quest_tracked65(id))continue;char title[160],lines[8][96];snprintf(title,sizeof(title),"%s",quest_title65(id));while(*title&&ui_text_width(title,1)>228)title[strlen(title)-1]=0;ui_light(25,y,1,title);ui_light(26,y,1,title);y+=16;int n=ui_wrap(quest_objective65(id),lines,228,.9f);if(n>4)n=4;for(int line=0;line<n;line++){ui_light(25,y,.9f,lines[line]);y+=13;}ui_quest_bar65(25,y,160,id);uint64_t done,total;if(quest_progress65(id,&done,&total))y+=8;if(id==CAMPAIGN_QUEST200){ui_light(25,y,.85f,"MAIN STORY");}else hud_quad(25,y,85,14,0,2016,85,14);y+=23;shown++;}}
